# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN ÇOCUKLUK YILLARINDAKİ ÖRNEK AHLAKI</text>\n  <rect x="20" y="48" width="155" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="97" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Doğruluk ve Güven</text>\n  <text x="97" y="102" text-anchor="middle" font-size="11" fill="#1e3a8a">• Çocukluğunda bile şaka</text>\n  <text x="97" y="120" text-anchor="middle" font-size="11" fill="#1e3a8a">yaparken dahi yalan</text>\n  <text x="97" y="138" text-anchor="middle" font-size="11" fill="#1e3a8a">söylememiştir.</text>\n  <text x="97" y="164" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">«Muhammedü\'l-Emîn»</text>\n  <text x="97" y="184" text-anchor="middle" font-size="11" fill="#1e3a8a">(Güvenilir Muhammed)</text>\n  <text x="97" y="204" text-anchor="middle" font-size="11" fill="#1e3a8a">unvanıyla tanınmıştır.</text>\n\n  <rect x="190" y="48" width="155" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="267" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kanaatkârlık</text>\n  <text x="267" y="102" text-anchor="middle" font-size="11" fill="#14532d">• Amcası Ebû Talip\'in</text>\n  <text x="267" y="120" text-anchor="middle" font-size="11" fill="#14532d">sofrasında «Bismillah»</text>\n  <text x="267" y="138" text-anchor="middle" font-size="11" fill="#14532d">diyerek önünden yemiştir.</text>\n  <text x="267" y="164" text-anchor="middle" font-size="11" fill="#14532d">• Açgözlülük yapmamış,</text>\n  <text x="267" y="182" text-anchor="middle" font-size="11" fill="#14532d">sofraya bereket ve şükür</text>\n  <text x="267" y="200" text-anchor="middle" font-size="11" fill="#14532d">getirmiştir.</text>\n\n  <rect x="360" y="48" width="155" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="437" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Çalışkanlık</text>\n  <text x="437" y="102" text-anchor="middle" font-size="11" fill="#78350f">• Kalabalık ailesi olan</text>\n  <text x="437" y="120" text-anchor="middle" font-size="11" fill="#78350f">amcasına yük olmamak</text>\n  <text x="437" y="138" text-anchor="middle" font-size="11" fill="#78350f">için çobanlık yapmıştır.</text>\n  <text x="437" y="164" text-anchor="middle" font-size="11" fill="#78350f">• Ticaret kervanlarına</text>\n  <text x="437" y="182" text-anchor="middle" font-size="11" fill="#78350f">katılarak alın teriyle</text>\n  <text x="437" y="200" text-anchor="middle" font-size="11" fill="#78350f">sorumluluk üstlenmiştir.</text>\n\n  <rect x="530" y="48" width="150" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="605" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Merhamet ve Vefa</text>\n  <text x="605" y="102" text-anchor="middle" font-size="11" fill="#831843">• Yetimlere, yoksullara</text>\n  <text x="605" y="120" text-anchor="middle" font-size="11" fill="#831843">ve canlılara şefkatle</text>\n  <text x="605" y="138" text-anchor="middle" font-size="11" fill="#831843">yaklaşmıştır.</text>\n  <text x="605" y="164" text-anchor="middle" font-size="11" fill="#831843">• Sütannesi, dadısı,</text>\n  <text x="605" y="182" text-anchor="middle" font-size="11" fill="#831843">amcası ve yengesine</text>\n  <text x="605" y="200" text-anchor="middle" font-size="11" fill="#831843">vefalı davranmıştır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN ÇOCUKLARLA İLETİŞİMİ VE SEVGİ DİLİ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Sevgi, Şefkat ve Değer Verme</text>\n  <text x="182" y="100" text-anchor="middle" font-size="12" fill="#1e3a8a">• Çocuklara rastladığında önce kendisi selam vermiş</text>\n  <text x="182" y="122" text-anchor="middle" font-size="12" fill="#1e3a8a">ve mübarek eliyle başlarını okşamıştır.</text>\n  <text x="182" y="148" text-anchor="middle" font-size="12" fill="#1e3a8a">• Çocukları kucağına almış, öpmüş ve onlarla</text>\n  <text x="182" y="168" text-anchor="middle" font-size="12" fill="#1e3a8a">şakalaşarak oyunlarına katılmıştır.</text>\n  <text x="182" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">«Merhamet etmeyene merhamet olunmaz.» (Hadis-i Şerif)</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sabır, Hoşgörü ve Eğitici Yaklaşım</text>\n  <text x="517" y="100" text-anchor="middle" font-size="12" fill="#14532d">• Enes bin Malik: «10 yıl hizmetinde bulundum;</text>\n  <text x="517" y="120" text-anchor="middle" font-size="12" fill="#14532d">bana bir kez bile \'öf\' demedi, azarlamadı.»</text>\n  <text x="517" y="148" text-anchor="middle" font-size="12" fill="#14532d">• Kuşu ölen küçük Umeyr\'i evinde ziyaret ederek</text>\n  <text x="517" y="168" text-anchor="middle" font-size="12" fill="#14532d">acısını paylaşmış ve teselli etmiştir.</text>\n  <text x="517" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Hataları kırmadan, tatlı dille ve öğütle düzeltmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">1. ÜNİTE DEĞERLENDİRMESİ: ÇOCUKLUK KRONOLOJİSİ VE MEKÂNLAR</text>\n  <rect x="20" y="48" width="660" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="350" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Hz. Muhammed\'in (s.a.v.) Çocukluk Yılları Zaman Çizelgesi</text>\n  <text x="350" y="104" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">• 571 (Mekke): Doğumu (Babası Abdullah, doğumundan önce vefat etmiştir - Yetim)</text>\n  <text x="350" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">• 0 - 4 Yaş (Sa\'d Yurdu): Sütannesi Hz. Halime ve sütkardeşi Şeyma\'nın yanında büyümesi</text>\n  <text x="350" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">• 6 Yaş (Medine - Ebvâ): Annesi Hz. Âmine\'nin Ebvâ köyünde vefatı (Ümmü Eymen\'in Mekke\'ye getirmesi)</text>\n  <text x="350" y="182" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">• 6 - 8 Yaş (Mekke): Dedesi Abdülmuttalip\'in şefkatli himayesi ve 8 yaşında dedesinin vefatı</text>\n  <text x="350" y="208" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">• 8 Yaş Sonrası: Amcası Ebû Talip ve yengesi Fâtıma binti Esed\'in yuvasında yetişmesi</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
